#include "stdafx.h"#include "Queue.h"#include "..\Lang.h"////~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~// Структура работы с задвижкойtypedef struct : public SPROLOZ  {  int nValue;  } Queue_EdgSH;//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~// Функция отображенияint PaintEdgSH(DefinePaint)  {  QueueP(Queue_EdgSH);  //  double dValue = 0;  CShEdg& sh = (CShEdg&)PipeSH;  //  dValue=sh.State_Flags;  double U=sh.U;  double I=sh.I;  char strMess[128]="";  char strMess2[128]="";  COLORREF clr=RGB(81,71,41);  if (sh.setEnable)		clr=RGB(226,205,115);  CMyBrush brush( hDC, clr );	brush.Rect( p->mRect );  if ((dValue!=0)&&(sh.setEnable))  {		if (dValue==1)		{			sprintf_s(strMess,"ГОТОВ К ПУСКУ\0");			sprintf_s(strMess2,"Uз=%4.1lfкВ, Iогр=%4.2lfА\0",U,I);		}		if (dValue==2)		{			sprintf_s(strMess,"ПУСК");			sprintf_s(strMess2,"ИДЕТ КОНТРОЛЬ");		}		if (dValue==3)		{			sprintf_s(strMess,"РЕЖИМ СТАБИЛИЗАЦИИ U");			sprintf_s(strMess2,"Uвых=%4.1lfкВ, Iн=%4.2lfА",U,I);		}		if (dValue==4)		{			sprintf_s(strMess,"РЕЖИМ ОГРАНИЧЕНИЯ Iн");			sprintf_s(strMess2,"Uвых=%4.1lfкВ, Iн=%4.2lfА",U,I);		}		if (dValue==5)		{			sprintf_s(strMess,"КЗ в нагрузке");			sprintf_s(strMess2,"");		}		RECT rcStr1=p->mRect;		rcStr1.bottom=p->mRect.top+(p->mRect.bottom-p->mRect.top)/2;		::DrawText( hDC, strMess, strlen(strMess), &rcStr1, DT_SINGLELINE|DT_VCENTER|DT_CENTER );		RECT rcStr2=p->mRect;		rcStr2.top=p->mRect.top+(p->mRect.bottom-p->mRect.top)/2;		::DrawText( hDC, strMess2,strlen(strMess2), &rcStr2, DT_SINGLELINE|DT_VCENTER|DT_CENTER );  }  return 1;  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~void AddEdgSH(DefineTegs)  {  //  AddQueueEx(Queue_EdgSH);  //  // Код, посылаемый в АРМ  p->btSendType = QUEUE_NO;  // Определение функции вывода  p->paint = &PaintEdgSH;  //  //  STegObj obj[] =    {    { 'R', "rect" , &p->mRect },    { 'E', "rc"   , &p->mRect },    // Дополнительная информация    EXT_QUEUE    };  //  ::ParserObjScn( teg, obj, sizeof(obj)/sizeof(STegObj) );  AddPRSH( def, id_Edg, teg[0].value, p, p->nValue );  //  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~